   183	/*
   184	 * Calculate the size of the SMB message based on the fixed header
   185	 * portion, the number of word parameters and the data portion of the message.
   186	 */
   187	static int smb2_calc_size(void *buf, unsigned int *len)
   188	{
   189		struct smb2_pdu *pdu = (struct smb2_pdu *)buf;
   190		struct smb2_hdr *hdr = &pdu->hdr;
   191		unsigned int offset; /* the offset from the beginning of SMB to data area */
   192		unsigned int data_length; /* the length of the variable length data area */
   193		int ret;
   194	
   195		/* Structure Size has already been checked to make sure it is 64 */
   196		*len = le16_to_cpu(hdr->StructureSize);
   197	
   198		/*
   199		 * StructureSize2, ie length of fixed parameter area has already
   200		 * been checked to make sure it is the correct length.
   201		 */
   202		*len += le16_to_cpu(pdu->StructureSize2);
   203		/*
   204		 * StructureSize2 of smb2_lock pdu is set to 48, indicating
   205		 * the size of smb2 lock request with single smb2_lock_element
   206		 * regardless of number of locks. Subtract single
   207		 * smb2_lock_element for correct buffer size check.
   208		 */
   209		if (hdr->Command == SMB2_LOCK)
   210			*len -= sizeof(struct smb2_lock_element);
   211	
   212		if (has_smb2_data_area[le16_to_cpu(hdr->Command)] == false)
   213			goto calc_size_exit;
   214	
   215		ret = smb2_get_data_area_len(&offset, &data_length, hdr);
   216		if (ret)
   217			return ret;
   218		ksmbd_debug(SMB, "SMB2 data length %u offset %u\n", data_length,
   219			    offset);
   220	
   221		if (data_length > 0) {
   222			/*
   223			 * Check to make sure that data area begins after fixed area,
   224			 * Note that last byte of the fixed area is part of data area
   225			 * for some commands, typically those with odd StructureSize,
   226			 * so we must add one to the calculation.
   227			 */
   228			if (offset + 1 < *len) {
   229				ksmbd_debug(SMB,
   230					    "data area offset %d overlaps SMB2 header %u\n",
   231					    offset + 1, *len);
   232				return -EINVAL;
   233			}
   234	
   235			*len = offset + data_length;
   236		}
   237	
   238	calc_size_exit:
   239		ksmbd_debug(SMB, "SMB2 len %u\n", *len);
   240		return 0;
   241	}
